/**
 * Prey1719FrenchVoyageurCampSector.js
 *
 * Chantier de Level Design 3 (v190) - Prey (2022) French Fur Trappers' Burnt Clearing Camp
 * 1:1 Canonical Level Design:
 * - Scorched ash clearing in the pine forest where French voyageurs establish their fortified fur-trading camp.
 * - Foothold steel-jaw bear traps concealed beneath layers of volcanic ash and charred pine needles.
 * - Heavy suspended iron tree cages, buffalo hide tents, and burning pine-tar pitch torches.
 * - Dense billowing sulfurous black powder smoke generated by synchronized flintlock musket volleys.
 */

export class Prey1719FrenchVoyageurCampSector {
  /**
   * @param {Object} options
   * @param {number} [options.bearTrapsConcealed=6] Nombre de pièges à mâchoires dissimulés sous la cendre
   * @param {number} [options.musketeersCount=12] Nombre de trappeurs armés de fusils à silex
   */
  constructor(options = {}) {
    this.bearTrapsConcealed = options.bearTrapsConcealed ?? 6;
    this.musketeersCount = options.musketeersCount ?? 12;

    // État runtime
    this.campInfiltrated = false;
    this.bearTrapsSprung = 0;
    this.blackPowderSmokeDensityPct = 0.0;
    this.musketeersEliminated = 0;
    this.suspendedCageUnlatched = false;
  }

  /**
   * S'infiltrer silencieusement dans le camp des trappeurs
   */
  infiltrateVoyageurCamp() {
    this.campInfiltrated = true;

    return {
      status: 'VOYAGEUR_CAMP_INFILTRATED_SILENTLY',
      perimeterFiresCount: 4,
      ashLayerThicknessCm: 3.5,
      ironCagesSuspended: 2,
      stealthEntrySecured: true
    };
  }

  /**
   * Déclencher ou désarmer un piège à ours à mâchoires en acier
   * @param {boolean} springTrap Déclencher délibérément le piège (pour diversion)
   */
  triggerConcealedBearTrap(springTrap = true) {
    if (this.bearTrapsConcealed <= 0) {
      return { status: 'NO_TRAPS_REMAINING', sprung: false };
    }

    this.bearTrapsConcealed -= 1;
    this.bearTrapsSprung += 1;

    return {
      status: springTrap ? 'STEEL_JAW_BEAR_TRAP_SNAPPED' : 'BEAR_TRAP_DISARMED',
      jawClampingForceNewtons: 4800.0,
      steelSnapAcousticDb: 92.0,
      diversionCreated: springTrap,
      trapsLeft: this.bearTrapsConcealed
    };
  }

  /**
   * Les trappeurs tirent une salve de mousquets créant un écran de fumée noire
   */
  unleashFlintlockMusketVolley() {
    this.blackPowderSmokeDensityPct = 85.0;

    return {
      status: 'BLACK_POWDER_MUSKET_VOLLEY_DISCHARGED',
      leadBallsFired: this.musketeersCount,
      sulfurSmokeDensityPct: this.blackPowderSmokeDensityPct,
      muzzleFlashLumens: 45000,
      visionOcclusionActive: true
    };
  }

  /**
   * Éliminer les trappeurs à travers l'écran de fumée
   * @param {number} count Nombre de mousquetaires abattus
   */
  eliminateVoyageurMusketeers(count = 6) {
    const eliminated = Math.min(this.musketeersCount, count);
    this.musketeersCount -= eliminated;
    this.musketeersEliminated += eliminated;

    return {
      status: 'VOYAGEUR_MUSKETEERS_ELIMINATED',
      eliminatedThisTurn: eliminated,
      totalEliminated: this.musketeersEliminated,
      musketeersRemaining: this.musketeersCount,
      campNeutralized: this.musketeersCount === 0
    };
  }
}
